/**
 * Verifies a synthetic seed through a fresh reader that starts no pieces locally.
 * This correctness probe is separate from uninstrumented navigation timings.
 */

import { expect } from "@std/expect";
import { join } from "@std/path";

import type { JSONSchema } from "@commonfabric/runner";
import { experimentalOptionsFromEnv } from "@commonfabric/runner";
import { watermarkCell } from "@commonfabric/runner/executor/watermark";

import {
  initializePiecesController,
  type PieceController,
} from "../../packages/patterns/integration/pieces-controller.ts";
import {
  crossrefTargets,
  seedIdentity,
  seedTopicBoard,
  topicAt,
} from "../../packages/patterns/integration/topic-board-fixture.ts";

const apiUrl = new URL(Deno.env.get("API_URL")!);
const runDir = Deno.env.get("CF_CAMPAIGN_RUN_DIR")!;
const spaceName = Deno.env.get("SPACE_NAME")!;
const expectedPosture =
  Deno.env.get("EXPERIMENTAL_SERVER_EXECUTION") === "true";
expect(experimentalOptionsFromEnv(Deno.env.get).serverExecution).toBe(
  expectedPosture,
);
const identity = await seedIdentity("server-execution topics campaign");
const shape = {
  topicCount: Number(Deno.env.get("CF_TOPIC_BOARD_TOPICS") ?? 5),
  crossrefsPerTopic: 2,
  citingTopics: 3,
  bodyWords: 120,
};
const fixture = await seedTopicBoard({ apiUrl, spaceName, identity, ...shape });
await Deno.writeTextFile(join(runDir, "fixture.json"), JSON.stringify(fixture));
await Deno.writeTextFile(
  join(runDir, "stats-after-seed.json"),
  await (await fetch(new URL("/api/health/stats", apiUrl))).text(),
);

const isolatedDemand: unknown[] = [];
for (const demand of ["index", "full"] as const) {
  const controller = await initializePiecesController({
    apiUrl,
    space: spaceName,
    identity,
  });
  let cancel: (() => void) | undefined;
  try {
    const result = (await controller.getPieceCell(fixture.boardId, false))
      .asSchema(undefined);
    const schema = result.getMetaRaw("schema") as JSONSchema | undefined;
    if (schema === undefined) throw new Error("Missing durable result schema.");
    await controller.synced();
    const before = await (await fetch(new URL("/api/health/stats", apiUrl)))
      .json();
    const selected = demand === "full"
      ? result
      : result.asSchema(schema).key("index");
    cancel = selected.sink(() => {});
    const value = await selected.pull();
    await controller.synced();
    const index = demand === "full"
      ? (value as { index: unknown[] }).index
      : value;
    expect(Array.isArray(index)).toBe(true);
    expect((index as { title: string }[]).map((row) => row.title)).toEqual(
      fixture.topics.map((topic) => topic.title),
    );
    const after = await (await fetch(new URL("/api/health/stats", apiUrl)))
      .json();
    isolatedDemand.push({
      demand,
      identity: controller.runtime.scopeKeyIdentity,
      space: controller.getSpace(),
      before: before.campaignSessionDemand,
      after: after.campaignSessionDemand,
    });
  } finally {
    await controller.runtime.idle();
    cancel?.();
    await controller.dispose();
  }
}
await Deno.writeTextFile(
  join(runDir, "isolated-demand.json"),
  JSON.stringify(isolatedDemand),
);

const reader = await initializePiecesController({
  apiUrl,
  space: spaceName,
  identity,
});
try {
  expect(reader.runtime.experimental.serverExecution).toBe(expectedPosture);
  const board = await reader.get(fixture.boardId, false);
  const actualTopics = await board.result.get(["topics"]) as unknown[];
  expect(actualTopics.length).toBe(shape.topicCount);
  const topics: PieceController[] = [];
  for (let index = 0; index < shape.topicCount; index++) {
    const topic = await topicAt(board, index);
    expect(topic.id).toBe(fixture.topics[index].fid);
    expect(await topic.result.get(["title"])).toBe(fixture.topics[index].title);
    const body = await topic.result.get(["body"]) as string;
    expect(body.split(" ").length).toBe(shape.bodyWords);
    topics.push(topic);
  }
  const edges: { from: string; to: string[] }[] = [];
  for (const [index, topic] of topics.entries()) {
    const mentions = (await topic.result.getCell()).key("mentions");
    await mentions.pull();
    const expected = crossrefTargets(index, shape);
    expect((mentions.get() as unknown[]).length).toBe(expected.length);
    for (const [position, target] of expected.entries()) {
      expect(
        mentions.key(position).resolveAsCell().equals(topics[target].getCell()),
      )
        .toBe(true);
    }
    edges.push({
      from: topic.id,
      to: expected.map((target) => topics[target].id),
    });
  }
  const index = await board.result.get(["index"]) as { title: string }[];
  expect(index.map((row) => row.title)).toEqual(
    fixture.topics.map((topic) => topic.title),
  );
  const watermark = expectedPosture
    ? await watermarkCell(reader.runtime, reader.getSpace()).pull()
    : null;
  console.log(JSON.stringify({
    clientPosture: reader.runtime.experimental.serverExecution,
    shape,
    verifiedTopics: topics.length,
    verifiedEdges: edges,
    watermarkObserved: watermark,
    watermarkCoverage: "not established by this readback probe",
  }));
} finally {
  await reader.dispose();
}

/**
 * Runs a Deno workload against CI's matching baked toolshed in a fresh store.
 * Saves exact commands, posture, load samples, raw output, and server statistics.
 * Usage: `deno run -A tools/server-execution-topics/run-arm.ts default DIR
 * correctness test -A packages/patterns/integration/EXAMPLE.test.ts`.
 * `latency` mode refuses a loaded machine and invalidates a run that gets busy.
 */

import { dirname, join, resolve } from "@std/path";

import {
  type CapabilityId,
  type Exec,
  openCapabilities,
} from "../../tasks/ci-capabilities.ts";
import {
  assertServerExecutionCiPosture,
  serverExecutionCiLane,
} from "../../tasks/server-execution-ci.ts";

const [role, directory, mode, ...args] = Deno.args;
if (
  (role !== "default" && role !== "opposite") || !directory ||
  (mode !== "correctness" && mode !== "latency" && mode !== "profile") ||
  args.length === 0
) {
  throw new Error(
    "Expected role, new artifact directory, mode, and Deno args.",
  );
}
const root = resolve(import.meta.dirname!, "../..");
const runDir = resolve(directory);
await Deno.mkdir(runDir);
const store = join(runDir, "store");
await Deno.mkdir(store);
const lane = serverExecutionCiLane(role);
const capability: CapabilityId = role === "default"
  ? "toolshed-baked"
  : "toolshed-baked-opposite";
const commands: { command: string; args: readonly string[]; cwd: string }[] =
  [];

/** Executes and records a setup command, placing this run's server in its store. */
const exec: Exec = async (command, commandArgs, options = {}) => {
  const cwd = command.endsWith(`toolshed-baked-${role}`)
    ? store
    : options.cwd ?? root;
  const index = commands.length;
  commands.push({ command, args: commandArgs, cwd });
  const result = await new Deno.Command(command, {
    args: [...commandArgs],
    cwd,
    env: options.env,
    stdout: "piped",
    stderr: "piped",
  }).output();
  await Deno.writeFile(join(runDir, `setup-${index}.stdout`), result.stdout);
  await Deno.writeFile(join(runDir, `setup-${index}.stderr`), result.stderr);
  if (!result.success) {
    throw new Error(`Setup command ${index} failed with exit ${result.code}.`);
  }
  return new TextDecoder().decode(result.stdout);
};

const samples: { at: string; load: number[] }[] = [];
const sampleLoad = () =>
  samples.push({
    at: new Date().toISOString(),
    load: Deno.loadavg(),
  });
sampleLoad();
const head = (await exec("git", ["rev-parse", "HEAD"])).trim();
const patch = await exec("git", ["diff", "HEAD", "--binary"]);
await Deno.writeTextFile(join(runDir, "worktree.patch"), patch);
const sourcePaths = [
  "tools/server-execution-topics/run-arm.ts",
  "tools/server-execution-topics/seed-check.ts",
  "packages/patterns/integration/topic-board-fixture.ts",
];
for (const path of sourcePaths) {
  const destination = join(runDir, "sources", path);
  await Deno.mkdir(dirname(destination), { recursive: true });
  await Deno.copyFile(join(root, path), destination);
}
const flags = Object.fromEntries(
  Object.entries(Deno.env.toObject()).filter(([key]) =>
    key.startsWith("EXPERIMENTAL_") ||
    key.startsWith("CF_TOPIC") ||
    ["CF_TIMING_MEASURES", "CF_MEMORY_FRAME_LOG", "CF_PROF_CPU"].includes(key)
  ),
);
flags.EXPERIMENTAL_SERVER_EXECUTION = String(lane.enabled);
const cpuModel = Deno.build.os === "darwin"
  ? (await exec("/usr/sbin/sysctl", ["-n", "machdep.cpu.brand_string"])).trim()
  : Deno.build.os === "linux"
  ? (await Deno.readTextFile("/proc/cpuinfo"))
    .match(/^model name\s*:\s*(.+)$/m)?.[1]
  : undefined;
const manifest: Record<string, unknown> = {
  version: 1,
  mode,
  role,
  expectedPosture: lane,
  workloadHead: head,
  sourcePaths,
  root,
  store,
  cache: "fresh store and server; existing Deno dependency cache",
  machine: {
    cpu: cpuModel,
    arch: Deno.build.arch,
    os: Deno.build.os,
    logicalCpus: navigator.hardwareConcurrency,
    totalmem: Deno.systemMemoryInfo().total,
  },
  runtime: Deno.version,
  flags,
  commands,
  samples,
  status: "preparing",
};
const save = () =>
  Deno.writeTextFile(
    join(runDir, "manifest.json"),
    JSON.stringify(manifest, null, 2) + "\n",
  );
await save();
if (
  mode === "latency" &&
  ["CF_TIMING_MEASURES", "CF_MEMORY_FRAME_LOG", "CF_PROF_CPU"].some((key) =>
    flags[key] !== undefined && !["", "0", "false"].includes(flags[key])
  )
) {
  manifest.status = "blocked-instrumentation";
  await save();
  throw new Error(
    "Latency runs must be separate from timing/frame/CPU profiling.",
  );
}
if (mode === "latency" && samples[0].load[0] > 5) {
  manifest.status = "blocked-load";
  await save();
  throw new Error("Latency run requires one-minute load at or below 5.");
}

let opened: Awaited<ReturnType<typeof openCapabilities>> | undefined;
let sampling: ReturnType<typeof setInterval> | undefined;
try {
  opened = await openCapabilities([capability], {
    root,
    dryRun: false,
    workDir: runDir,
    exec,
  });
  const endpoint = opened.envFor([capability]);
  const meta = await (await fetch(`${endpoint.API_URL}/api/meta`)).json();
  const before = await (await fetch(`${endpoint.API_URL}/api/health/stats`))
    .json();
  assertServerExecutionCiPosture(role, meta, before);
  if (meta.gitSha !== head) {
    throw new Error(
      `Server build ${meta.gitSha} does not match workload head ${head}. ` +
        "Rebuild both binaries with COMMIT_SHA set to the workload head.",
    );
  }
  manifest.meta = meta;
  manifest.serverBuildHead = meta.gitSha;
  await Deno.writeTextFile(
    join(runDir, "stats-before.json"),
    JSON.stringify(before),
  );
  const binary = join(root, ".ci-cache/binaries", `toolshed-baked-${role}`);
  manifest.binarySha256 = (await exec("shasum", ["-a", "256", binary]))
    .split(" ")[0];
  const env = {
    ...endpoint,
    ...flags,
    FRONTEND_URL: endpoint.API_URL,
    SPACE_NAME: `topics-campaign-${crypto.randomUUID()}`,
    HEADLESS: "1",
    CF_LOG_LEVEL: "silent",
    CF_CAMPAIGN_RUN_DIR: runDir,
  };
  manifest.workloadEnvironment = env;
  commands.push({ command: Deno.execPath(), args, cwd: root });
  sampleLoad();
  // Periodic samples observe contention during the workload; they do not
  // delay it or determine when its completion conditions have been reached.
  sampling = setInterval(sampleLoad, 1000);
  manifest.status = "running";
  await save();
  const result = await new Deno.Command(Deno.execPath(), {
    args,
    cwd: root,
    env,
    stdout: "piped",
    stderr: "piped",
  }).output();
  clearInterval(sampling);
  sampling = undefined;
  sampleLoad();
  await Deno.writeFile(join(runDir, "workload.stdout"), result.stdout);
  await Deno.writeFile(join(runDir, "workload.stderr"), result.stderr);
  const after = await (await fetch(`${endpoint.API_URL}/api/health/stats`))
    .json();
  await Deno.writeTextFile(
    join(runDir, "stats-after.json"),
    JSON.stringify(after),
  );
  manifest.exitCode = result.code;
  manifest.latencyEligible = mode === "latency" &&
    samples.every(({ load }) => load[0] <= 5);
  manifest.status = !result.success
    ? "failed-workload"
    : mode === "latency" && manifest.latencyEligible !== true
    ? "invalid-load"
    : "passed";
  await save();
  if (!result.success) {
    throw new Error(`Workload failed with exit ${result.code}.`);
  }
  if (manifest.status === "invalid-load") {
    throw new Error(
      "Machine load exceeded the latency threshold during this run.",
    );
  }
} catch (error) {
  manifest.error = error instanceof Error ? error.message : String(error);
  if (manifest.status === "preparing" || manifest.status === "running") {
    manifest.status = "failed";
  }
  await save();
  throw error;
} finally {
  if (sampling !== undefined) clearInterval(sampling);
  await opened?.close();
}

/**
 * Builds a topic board carrying enough synthetic material that opening it
 * exercises the parts of the runtime only large boards reach: a long card list,
 * a prose corpus wide enough for the crossref join to cost something, and one
 * child piece per topic for storage to load.
 *
 * Every topic's title and body are derived from its index, so two runs of the
 * same size produce the same board and their timings are comparable.
 *
 * Seeding holds the whole board live while it writes, and the board recomputes
 * its crossref join on each write, so peak memory rises with the topic count.
 * {@link seedTopicBoardOutOfProcess} runs the seed in a child Deno with a heap
 * of its own, which is how a benchmark gets a large board without carrying that
 * peak for the rest of its run.
 */

import { Identity } from "@commonfabric/identity";
import { resolveLocalProgram } from "@commonfabric/runner/local-program.deno";
import { runDenoCommandWithTemporaryLock } from "@commonfabric/test-support/isolated-deno";
import { join } from "@std/path";
import {
  initializePiecesController,
  PieceController,
} from "./pieces-controller.ts";

/** One seeded topic, addressed the way the board's links address it. */
export interface SeededTopic {
  /** The topic piece's tagged hash (`fid1:…`), as pasted into prose. */
  fid: string;
  title: string;
}

export interface TopicBoardFixture {
  /** The space the board lives in. */
  spaceName: string;

  /** The board piece, for the shell's `/spaceName/pieceId` route. */
  boardId: string;

  /** Seeded topics in creation order. */
  topics: SeededTopic[];
}

export interface SeedTopicBoardOptions {
  apiUrl: URL;
  spaceName: string;
  identity: Identity;

  /** How many topics the board carries. */
  topicCount: number;

  /**
   * How many earlier topics a citing body cites. Every citation is an edge the
   * board's crossref join has to find, and a link its cards render.
   */
  crossrefsPerTopic?: number;

  /**
   * How many of the topics cite anything, counted back from the newest. See
   * {@link DEFAULT_CITING_TOPICS} for why this is not every topic.
   */
  citingTopics?: number;

  /** Words of prose in each topic body. */
  bodyWords?: number;

  /** Called after each topic lands, with its index. */
  onTopic?: (index: number) => void;
}

export const DEFAULT_CROSSREFS_PER_TOPIC = 2;
export const DEFAULT_BODY_WORDS = 120;

/**
 * How many topics carry citations, counted back from the newest.
 *
 * Citations are what a board can least afford. The board recomputes its whole
 * crossref join on every write and the rows it builds carry cited siblings as
 * pieces, so each edge costs the seeding runtime far more than each topic does.
 * A thirty-topic board whose newest three topics cite two earlier ones each
 * seeds in about half a minute and peaks near two and a half gigabytes; six
 * citing topics doubles that peak, and citing from every topic exhausts an
 * eight-gigabyte heap around the twentieth topic. Keeping the citations few
 * leaves the prose corpus — the part that grows with the board — as large as
 * the board is.
 *
 * The newest topics are the ones that cite, because the board orders its cards
 * by last activity, so those are the cards a reader reaches first.
 */
export const DEFAULT_CITING_TOPICS = 3;

const AGENT_NAME = "Topic board benchmark";

/**
 * Vocabulary the generated prose draws from. Any list of words does; these
 * ones keep a generated body readable when a run is inspected by hand.
 */
const WORDS = [
  "attention",
  "boundary",
  "capture",
  "durable",
  "envelope",
  "fabric",
  "gather",
  "handoff",
  "interval",
  "journal",
  "kernel",
  "ledger",
  "moment",
  "notice",
  "outline",
  "pattern",
  "quorum",
  "record",
  "surface",
  "thread",
  "update",
  "vantage",
  "witness",
  "yield",
];

/** Title of the topic at `index`, the same for a board of any size. */
export function topicTitle(index: number): string {
  return `Topic ${String(index).padStart(4, "0")} ${
    WORDS[index % WORDS.length]
  }`;
}

/**
 * Indices of the topics the topic at `index` cites on a board of `topicCount`
 * topics, newest citation first. Only earlier topics can be cited: a body is
 * written at creation, when no later topic has a fid yet. Only the newest
 * `citingTopics` cite at all.
 *
 * The citations are spread evenly over everything earlier, so one reaches the
 * far end of the board as readily as it reaches the neighbour, and the crossref
 * join has to look at scattered entries rather than a run of adjacent ones. The
 * first is always the immediate predecessor, which is the link the navigation
 * benchmark follows.
 *
 * A topic cites `crossrefsPerTopic` siblings whenever it has that many earlier
 * ones to cite, and every earlier sibling when it does not. The count is
 * therefore bounded only by the board, and the shortfall near the start of one
 * is exact rather than incidental.
 */
export function crossrefTargets(
  index: number,
  {
    topicCount,
    crossrefsPerTopic = DEFAULT_CROSSREFS_PER_TOPIC,
    citingTopics = DEFAULT_CITING_TOPICS,
  }: {
    topicCount: number;
    crossrefsPerTopic?: number;
    citingTopics?: number;
  },
): number[] {
  if (index < topicCount - citingTopics) return [];
  const earlier = index;
  const count = Math.min(crossrefsPerTopic, earlier);
  const targets: number[] = [];
  for (let citation = 0; citation < count; citation++) {
    targets.push(index - 1 - Math.floor((citation * earlier) / count));
  }
  return targets;
}

/**
 * `wordCount` words of prose derived from `index`. The stride varies with the
 * index so successive topics do not share a prefix, and a body is not folded
 * away by a layer that stores repeated text once.
 */
function topicProse(index: number, wordCount: number): string {
  const stride = 1 + (index % (WORDS.length - 1));
  const words: string[] = [];
  for (let i = 0; i < wordCount; i++) {
    words.push(WORDS[(index + i * stride) % WORDS.length]);
  }
  return words.join(" ");
}

/**
 * The body of the topic at `index`. Prose only: what this topic references is
 * recorded as references through `mention`, not written into the sentence.
 */
function topicBody(
  index: number,
  shape: { bodyWords: number },
): string {
  return topicProse(index, shape.bodyWords);
}

/**
 * The topic piece at `index` in the board's list.
 *
 * Only the `topics` key is pulled. The board's result also carries `crossrefs`,
 * whose rows are piece-valued and expand through each topic's view of every
 * sibling; pulling the whole result grows without bound as the board fills.
 */
export async function topicAt(
  board: PieceController,
  index: number,
): Promise<PieceController> {
  const topics = (await board.result.getCell()).key("topics");
  await topics.pull();
  return new PieceController(
    board.pieces(),
    topics.key(index).resolveAsCell(),
  );
}

/**
 * Create a board in `spaceName` and fill it with `topicCount` topics. The
 * controller that authors the board is disposed before this returns, so the
 * seeded space is left to whatever reads it next with no connection of ours
 * still open.
 */
export async function seedTopicBoard(
  options: SeedTopicBoardOptions,
): Promise<TopicBoardFixture> {
  const shape = {
    topicCount: options.topicCount,
    crossrefsPerTopic: options.crossrefsPerTopic ?? DEFAULT_CROSSREFS_PER_TOPIC,
    citingTopics: options.citingTopics ?? DEFAULT_CITING_TOPICS,
    bodyWords: options.bodyWords ?? DEFAULT_BODY_WORDS,
  };

  const cc = await initializePiecesController({
    space: options.spaceName,
    apiUrl: options.apiUrl,
    identity: options.identity,
  });
  let releaseBoard: (() => void) | undefined;
  try {
    await cc.ensureDefaultPattern();

    const sourcePath = join(import.meta.dirname!, "..", "topics", "main.tsx");
    const rootPath = join(import.meta.dirname!, "..");
    const program = await resolveLocalProgram(
      (resolver) => cc.runtime.harness.resolve(resolver),
      { main: sourcePath, root: rootPath },
    );
    const board = await cc.create(program, { start: true });

    // Hold the board's result live for the duration of the seed, so each
    // `addTopic` lands against an up-to-date list.
    releaseBoard = cc.getResult(board.getCell()).sink(() => {});

    const topics: SeededTopic[] = [];
    // The created pieces themselves, because a mention is a reference: the
    // fid is what the fixture reports, not what it seeds an edge with.
    const pieces: PieceController[] = [];
    for (let index = 0; index < options.topicCount; index++) {
      const title = topicTitle(index);
      await board.result.set({
        title,
        body: topicBody(index, shape),
        agentName: AGENT_NAME,
      }, ["addTopic"]);
      const created = await topicAt(board, index);
      // Each citation is a REFERENCE, recorded through the topic's own verb.
      // Writing `See also fid1:…` into the body used to make an edge; nothing
      // reads prose for addresses now, so a seeded board built that way would
      // carry the sentences and none of the graph — and every benchmark over it
      // would quietly measure a board with no crossrefs at all.
      for (const target of crossrefTargets(index, shape)) {
        await created.result.set({ topic: pieces[target].getCell() }, [
          "mention",
        ]);
      }
      pieces.push(created);
      topics.push({ fid: created.id, title });
      options.onTopic?.(index);
    }

    return { spaceName: options.spaceName, boardId: board.id, topics };
  } finally {
    releaseBoard?.();
    await cc.dispose();
  }
}

export interface SeedTopicBoardOutOfProcessOptions {
  apiUrl: URL;
  spaceName: string;

  /** Passphrase the child derives the seeding identity from. */
  passphrase: string;
  topicCount: number;
  crossrefsPerTopic?: number;
  citingTopics?: number;
  bodyWords?: number;

  /** Heap ceiling for the child, in megabytes. */
  heapMegabytes?: number;
}

/**
 * Peak heap while seeding rises with the topic count, so a board large enough
 * to be worth measuring is seeded well above the heap a benchmark process
 * otherwise needs. Raising the ceiling for one child costs the parent nothing.
 */
export const DEFAULT_SEED_HEAP_MEGABYTES = 8192;

const REPO_ROOT = join(import.meta.dirname!, "..", "..", "..");

/**
 * Seed a board in a child Deno and return what it wrote. The child exits when
 * the board is complete, so its peak heap is gone before the caller reads the
 * fixture.
 */
export async function seedTopicBoardOutOfProcess(
  options: SeedTopicBoardOutOfProcessOptions,
): Promise<TopicBoardFixture> {
  const script = join(import.meta.dirname!, "topic-board-seed.ts");
  const outputDirectory = await Deno.makeTempDir({
    prefix: "commonfabric-topic-board-",
  });
  const output = join(outputDirectory, "fixture.json");
  try {
    const heap = options.heapMegabytes ?? DEFAULT_SEED_HEAP_MEGABYTES;
    const result = await runDenoCommandWithTemporaryLock({
      root: REPO_ROOT,
      args: (lockPath) => [
        "run",
        "--lock",
        lockPath,
        "--no-check",
        `--v8-flags=--max-old-space-size=${heap}`,
        "-A",
        script,
        `--api-url=${options.apiUrl.href}`,
        `--space=${options.spaceName}`,
        `--passphrase=${options.passphrase}`,
        `--topics=${options.topicCount}`,
        `--crossrefs=${
          options.crossrefsPerTopic ?? DEFAULT_CROSSREFS_PER_TOPIC
        }`,
        `--citing-topics=${options.citingTopics ?? DEFAULT_CITING_TOPICS}`,
        `--body-words=${options.bodyWords ?? DEFAULT_BODY_WORDS}`,
        `--out=${output}`,
      ],
    });
    if (!result.success) {
      throw new Error(
        `Seeding a ${options.topicCount}-topic board failed (exit ${result.code}):\n${
          new TextDecoder().decode(result.stderr)
        }`,
      );
    }
    return JSON.parse(await Deno.readTextFile(output)) as TopicBoardFixture;
  } finally {
    await Deno.remove(outputDirectory, { recursive: true });
  }
}

/** The identity a seeded board is authored by, and read back with. */
export function seedIdentity(passphrase: string): Promise<Identity> {
  return Identity.fromPassphrase(passphrase, { implementation: "noble" });
}

